import { booleanAttribute, ChangeDetectionStrategy, Component, computed, ElementRef, forwardRef, inject, input, OnInit, signal, ViewChild } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective } from 'espd-common/forms/api';
import { ControlLabelComponent } from 'espd-common/forms/control-label';
import { MessageComponent } from 'espd-common/i18n';

@Component({
	selector: 'espd-switch',
	templateUrl: 'switch.component.html',
	styleUrl: 'switch.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => SwitchComponent) }],
	imports: [
		ControlLabelComponent,
		MessageComponent,
		ReactiveFormsModule
	],
	host: {
		'[class.checked]': 'checked()',
		'[class.small]': 'small()',
		'[class.disabled]': 'disabledSignal()',
		'[class]': 'colorClass()'
	}
})
export class SwitchComponent extends EspdAbstractInputDirective implements OnInit {

	@ViewChild('input')
	private inputElement?: ElementRef;

	color = input<'primary' | 'success' | 'warning' | 'danger' | 'info' | 'dark'>('success');
	small = input(false, { transform: booleanAttribute });
	colorClass = computed(() => `switch-${this.color()}`);
	checked = signal(false);
	disabledSignal = signal(false);
	element = inject(ElementRef);

	ngOnInit(): void {
		super.ngOnInit();
		this.checked.set(this.control.value);
		this.disabledSignal.set(this.control.disabled);
		this.control.valueChanges.subscribe(value => this.checked.set(!!value));
		this.control.registerOnDisabledChange(disabled => this.disabledSignal.set(disabled));
	}

	public focus(target: 'control' | 'container'): void {
		(target === 'control'
			? this.inputElement
			: this.element
		)?.nativeElement.focus();
	}
}